import React, { useEffect, useState } from "react";
import { csv } from "d3-fetch";
import {
  ComposableMap,
  Geographies,
  Geography,
  Sphere,
  Marker,
} from "react-simple-maps";
import { Container } from "@mui/material";
import sortBy from "lodash/sortBy";
import locationIcon from "../../assets/images/map-pin.svg";
import omanFlag from "../../assets/images/omanFlag.png";

const geoUrl = "/features.json";

const MapChart = () => {
  const [data, setData] = useState([]);
  const [city, setCity] = useState([]);
  const [maxValue, setMaxValue] = useState([]);
  const [hoverInfo, setHoverInfo] = useState(null);
  const [hoverVisible, setHoverVisible] = useState(false);

  useEffect(() => {
    csv(`/vulnerability.csv`).then((data) => {
      setData(data);
    });
  }, []);

  useEffect(() => {
    csv("/data.csv").then((cities) => {
      const sortedCities = sortBy(cities, (o) => -o.population);
      setMaxValue(sortedCities[0].population);
      setCity(sortedCities);
    });
  }, []);

  const markers = [
    {
      markerOffset: -15,
      name: "Muscat",
      coordinates: [58.5933, 23.588],
      country: "Oman",
    },
    // Add more markers as needed
  ];

  const flagMap = {
    Oman: "https://upload.wikimedia.org/wikipedia/commons/d/dd/Flag_of_Oman.svg",
    USA: "https://upload.wikimedia.org/wikipedia/en/a/a4/Flag_of_the_United_States.svg",
    Argentina:
      "https://upload.wikimedia.org/wikipedia/commons/1/1a/Flag_of_Argentina.svg",
    // Add more countries and their flag URLs here
  };

  const handleMouseEnter = (info) => {
    setHoverInfo(info);
    setHoverVisible(true);
  };

  const handleMouseLeave = () => {
    setHoverVisible(false);
    setTimeout(() => setHoverInfo(null), 300); // Delay setting hoverInfo to null to match the transition duration
  };

  return (
    <Container maxWidth={"lg"} disableGutters>
      <ComposableMap projectionConfig={{ rotate: [-10, 0, 0], scale: 207 }}>
        {/* <ComposableMap
        projectionConfig={{
          rotate: [-57, -20, 0], // Adjust to focus on Oman (longitude: 57, latitude: 20)
          scale: 350, // Increase scale for zooming in
        }}
      > */}
        <defs>
          <pattern
            id="hollow-hexagon-pattern"
            patternUnits="userSpaceOnUse"
            width="30"
            height="32"
            patternTransform="rotate(90) scale(0.2) translate(8, 8)"
          >
            <polygon
              points="10,1 2,5.5 2,16.5 10,21 18,16.5 18,5.5"
              fill="none"
              stroke="#666"
              strokeWidth="1"
            />
          </pattern>
        </defs>
        <Sphere stroke="#fff" strokeWidth={0.5} />
        {data.length > 0 && (
          <Geographies geography={geoUrl}>
            {({ geographies }) =>
              geographies.map((geo) => (
                <Geography
                  key={geo.rsmKey}
                  geography={geo}
                  fill="url(#hollow-hexagon-pattern)"
                  stroke="none"
                />
              ))
            }
          </Geographies>
        )}
        {markers.map(({ name, coordinates, markerOffset, country }) => (
          <Marker
            key={name}
            coordinates={coordinates}
            onMouseEnter={() => handleMouseEnter({ name, country })}
            onMouseLeave={handleMouseLeave}
            onClick={() =>
              window.open(
                `https://maps.app.goo.gl/CBW47Gg54mZ6c6Dh8`,
                "_blank" // Open in a new tab
              )
            }
          >
            <defs>
              <filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">
                <feDropShadow
                  dx="0" // Horizontal offset of the shadow
                  dy="1" // Vertical offset of the shadow
                  stdDeviation="4" // Blur radius
                  floodColor="#003350" // Shadow color
                  floodOpacity="0.22" // Shadow opacity (approximately #00335038)
                />
              </filter>
              <clipPath id="clip">
                <circle cx="25" cy="25" r="25" />{" "}
                {/* Adjusted radius to match the circle */}
              </clipPath>
            </defs>
            <g transform="translate(-25, -30)" style={{ cursor: "pointer" }}>
              {/* Circle background */}
              <circle
                cx="25" // Center x-coordinate of the circle
                cy="25" // Center y-coordinate of the circle
                r="25" // Radius of the circle
                fill="#fff" // Background color
                stroke="#ffff" // Border color
                strokeWidth="6" // Border width
                filter="url(#shadow)" // Apply the shadow filter
              />
              {/* Flag image */}
              <image
                // href={flagMap[country]} // Use the flag URL from flagMap
                href={omanFlag} // Use the flag URL from flagMap
                x="-30" // Align the top-left corner of the image with the circle's center
                y="-39"
                width="110" // Match circle diameter
                height="120" // Match circle diameter
                clipPath="url(#clip)" // Apply circular clipping to the image
              />
              {/* Background for Text */}
              <rect
                x="58" // Position to the right of the circle
                y={markerOffset + 27} // Adjust y to move the background rectangle down
                width="67" // Width of the background rectangle
                height="25" // Height of the background rectangle
                rx="12" // Border radius for rounded corners
                ry="12" // Border radius for rounded corners
                fill="#fff" // Background color
                stroke="none"
                filter="url(#shadow)" // Apply the shadow filter
              />
              {/* Text on top of the background */}
              <text
                x="90" // x-coordinate to center text horizontally in the rectangle
                y={markerOffset + 42} // Adjust y to move the text down
                textAnchor="middle" // Align text to the middle of the x-coordinate
                dominantBaseline="middle" // Center text vertically
                style={{
                  fill: "#201D28",
                  filter: "url(#shadow)",
                }} // Text styling and shadow
              >
                {country}
              </text>
            </g>
          </Marker>
        ))}

        {hoverInfo && (
          <g
            style={{
              transition: "opacity 1s ease, transform 1s ease",
              opacity: hoverVisible ? 1 : 0,
              transform: hoverVisible ? "translateY(0)" : "translateY(-10px)",
            }}
          >
            <rect
              x={530} // Position where you want to display the info window
              y={225} // Position where you want to display the info window
              rx="20" // Border radius for rounded corners
              ry="20" // Border radius for rounded corners
              fill="#fff" // Background color
              stroke="none"
              filter="url(#shadow)" // Apply the shadow filter
              style={{
                boxShadow: "0px 1px 4px 0px #00335038", // Box shadow
              }}
              width="231" // Width of the info window
              height="90" // Height of the info window
            />
            <text
              x={543} // Position the heading text inside the info window
              y={250} // Position the heading text
              style={{
                fill: "#201D28",
                fontSize: 16,
                fontWeight: 400,
              }}
            >
              {hoverInfo.name}
            </text>
            <image
              href={locationIcon} // Use the actual image URL
              x={540} // Position the image below the heading
              y={270} // Position the image below the heading
              width={20} // Width of the image
              height={20} // Height of the image
            />
            <text
              x={550} // Position the text to the right of the image
              y={280} // Align text with the middle of the image
              style={{ fill: "#8795AA", fontSize: 12 }}
            >
              <tspan x={570} dy="0">
                General Federation of Oman
              </tspan>
              <tspan x={570} dy="1.5em">
                Workers Street 133, First Floor
              </tspan>
            </text>
          </g>
        )}
      </ComposableMap>
    </Container>
  );
};

export default MapChart;
